template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 100mm;
  height: 70mm;
  padding: 3.5mm 3.8mm 2.8mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.media {
  display: flex;
  gap: 3.2mm;
  align-items: flex-start;
  min-height: 0;
}
img.product {
  width: 24mm;
  height: 24mm;
  object-fit: cover;
  border: 0.25mm solid #111;
  flex: 0 0 auto;
}
img.product[src=""] {
  display: none;
}
.info {
  flex: 1 1 auto;
  min-width: 0;
}
.name {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.2;
  max-height: 2.4em;
  overflow: hidden;
}
.category {
  font-size: 11px;
  margin-top: 1mm;
  color: #444;
}
.price {
  font-size: 32px;
  font-weight: 800;
  margin-top: 2.2mm;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 14px;
  font-weight: 700;
  margin-left: 1.2mm;
}
.meta {
  font-size: 11px;
  margin-top: 1.5mm;
  color: #444;
}
img.qr {
  width: 16mm;
  height: 16mm;
  flex: 0 0 auto;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6mm;
  margin-top: auto;
  width: 100%;
}
img.barcode {
  height: 18mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
.code {
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-align: center;
  white-space: nowrap;
}
